module Top;
  bit clk, en;
  int n;
  initial forever begin @(posedge clk iff en); n++; end
  initial begin
    #1 en = 1;
    #1 clk = 1; en = 0;
    #1 clk = 0;
    #1 en = 1;
    #1 en = 0; clk = 1;
    #1 clk = 0; en = 1;
    #1 $display("n=%0d", n);
    $finish;
  end
endmodule

module Top;
  bit clk, en;
  int n;
  initial forever begin @(posedge clk iff en); n++; end
  initial begin
    #1 en <= 1; clk <= 1;
    #1 clk <= 0;
    #1 en <= 0; clk <= 1;
    #1 clk <= 0; en <= 1;
    #1 clk <= 1; en <= 0;
    #1 $display("n=%0d", n);
    $finish;
  end
endmodule
